def create_provider_publication_scopes(apps, schema_editor):
    """Create the stable lock row for every profile that predates publication."""

    ProviderProfile = apps.get_model("services", "ProviderProfile")
    ProviderPublicationScope = apps.get_model(
        "services", "ProviderPublicationScope"
    )
    ProviderPublicationScope.objects.bulk_create(
        [
            ProviderPublicationScope(profile_id=profile_id)
            for profile_id in ProviderProfile.objects.values_list("id", flat=True)
        ],
        ignore_conflicts=True,
    )


